from h import *
I=[]
FV_ES="Porciones de fruta/verdura"; FV_AR="حصص الفاكهة/الخضار"
def fv(n): return [[FV_ES,f"Porciones de fruta/verdura por ración: {n}"]],[[FV_AR,f"حصص الفاكهة/الخضار لكل حصة: {n}"]]
I.append((7014811,{
"es":L("Pollo al estilo marroquí","Sirva este plato con cuscús para disfrutar de un verdadero manjar del norte de África.","4","212g",
["4 muslos grandes de pollo sin piel (100g cada uno)","4 ramas de canela","2 dientes de ajo, machacados","2 cucharaditas de pimentón","1 cucharadita de comino","1 cucharada de aceite de oliva","2 zanahorias, picadas","150g de ejotes franceses, cortados por la mitad","1 cucharadita de cúrcuma","25g de aceitunas verdes","75g de orejones de albaricoque listos para comer","ralladura y jugo de 1 limón","2 cucharadas de menta fresca picada, más un poco para decorar","200ml de caldo de pollo bajo en sal","pimienta negra recién molida"],
["Envuelva cada muslo de pollo alrededor de una rama de canela.","Mezcle el ajo, el pimentón, el comino y la mitad del aceite. Coloque el pollo en un recipiente no metálico, vierta con una cuchara la mezcla de especias y cúbralo bien; luego déjelo marinar durante al menos 1 hora.","Caliente el aceite restante en una sartén, añada las piezas de pollo (aún enrolladas alrededor de la rama de canela) y dórelas por todos lados. Retírelas de la sartén con una espumadera y reserve.","Añada la zanahoria y los ejotes a la sartén y cocine a fuego bajo durante unos 5 a 6 minutos. Incorpore la cúrcuma y agregue a la sartén todos los demás ingredientes, junto con el pollo.","Vierta el caldo, lleve a ebullición, tape y cocine a fuego lento de 12 a 15 minutos, hasta que el pollo esté tierno.","Sazone, decore con menta y sirva con abundante cuscús al vapor."],
["Si no tiene ramas de canela, agregue 1 cucharadita de canela molida a la marinada.","Como alternativa sin gluten, sirva con arroz basmati espolvoreado con granos de granada.","Instrucciones para congelar: Se puede congelar una vez cocido. Luego descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.",*fv(1)[0]]),
"ar":L("دجاج على الطريقة المغربية","قدّم هذا الطبق مع الكسكس لتستمتع بوجبة شمال أفريقية حقيقية.","4","212 غ",
["4 أفخاذ دجاج كبيرة منزوعة الجلد (100 غ لكل واحد)","4 أعواد قرفة","2 فص ثوم، مهروس","2 ملعقة صغيرة بابريكا","1 ملعقة صغيرة كمون","1 ملعقة كبيرة زيت زيتون","2 جزرة، مفرومة","150 غ فاصولياء خضراء فرنسية، مقطوعة إلى نصفين","1 ملعقة صغيرة كركم","25 غ زيتون أخضر","75 غ مشمش مجفف جاهز للأكل","قشر مبشور وعصير 1 ليمونة","2 ملعقة كبيرة نعناع طازج مفروم، بالإضافة إلى قليل منه للتزيين","200 مل مرق دجاج قليل الملح","فلفل أسود مطحون طازجًا"],
["لُفّ كل فخذ دجاج حول عود قرفة.","اخلط الثوم والبابريكا والكمون ونصف كمية الزيت. ضع الدجاج في وعاء غير معدني، وضع خليط التوابل بالملعقة وغطِّه به، ثم اتركه ليتتبل لمدة ساعة واحدة على الأقل.","سخّن الزيت المتبقي في مقلاة، وأضف قطع الدجاج (وما زالت ملفوفة حول عود القرفة) وحمّرها من كل الجهات. أخرجها من المقلاة بملعقة مثقبة وضعها جانبًا.","أضف الجزر والفاصولياء إلى المقلاة، واطهُ على نار هادئة لحوالي 5–6 دقائق. أضف الكركم، ثم أضف جميع المكونات المتبقية إلى المقلاة مع الدجاج.","اسكب المرق، واتركه حتى يغلي، ثم غطِّه واتركه على نار هادئة من 12 إلى 15 دقيقة، حتى يلين الدجاج.","تبّله وزيّنه بالنعناع وقدّمه مع الكثير من الكسكس المطهو على البخار."],
["إذا لم تتوفر لديك أعواد القرفة، فأضف 1 ملعقة صغيرة من القرفة المطحونة إلى التتبيلة.","كبديل خالٍ من الغلوتين، قدّمه مع أرز بسمتي مرشوش بحبوب الرمان.","تعليمات التجميد: مناسب للتجميد بعد الطهي. ثم ذوّبه في الثلاجة أو الميكروويف وأعد تسخينه حتى يسخن تمامًا من الداخل.",*fv(1)[1]])}))
I.append((7014881,{
"es":L("Pollo jerk con salsa de piña a la parrilla","Un plato jamaiquino clásico, popular en todo el Caribe. Jerk se refiere al condimento picante en el que se marina el pollo. Se puede cocinar en el horno o en la barbacoa.","4","385g",
["8 muslos de pollo pequeños, deshuesados (720g)","3 bayas de pimienta de Jamaica","1 cucharadita de nuez moscada molida","1 cucharadita de canela molida","1 cebolla morada pequeña, rallada finamente","4 cebolletas, recortadas y finamente picadas","1 chile rojo, sin semillas y finamente picado","1 lima, rallada finamente (ralladura y jugo)",["Para la salsa de piña","1 piña fresca mediana, sin cáscara, u 8 rodajas de piña en lata"],["Para la salsa de piña","aceite en spray de 1 caloría"],["Para la salsa de piña","1 chile verde, sin semillas y finamente picado"],["Para la salsa de piña","1 lima, solo el jugo"],["Para la salsa de piña","½ cebolla morada pequeña, finamente picada"],["Para la salsa de piña","un puñado pequeño de cilantro fresco, finamente picado"],["Para la ensalada de zanahoria y manzana","2 zanahorias, peladas y ralladas grueso"],["Para la ensalada de zanahoria y manzana","1 manzana Granny Smith, sin corazón y rallada gruesa"],["Para la ensalada de zanahoria y manzana","2 cucharaditas de vinagre de sidra de manzana"],["Para la ensalada de zanahoria y manzana","1 cucharada de semillas de girasol"]],
["Con un cuchillo afilado, haga varios cortes en la carne del pollo y colóquelo en un recipiente no metálico. Tueste en seco las bayas de pimienta de Jamaica de 2 a 3 minutos hasta que desprendan aroma, luego páselas a un mortero y macháquelas hasta obtener un polvo. Añada los demás ingredientes del jerk y machaque hasta formar una pasta espesa. Mézclela con el pollo para cubrirlo de manera uniforme. Tape y deje marinar durante la noche si tiene tiempo, o al menos 1 hora.","Mientras tanto, corte y deseche el corazón de la piña y corte la pulpa en rodajas. Caliente una sartén grill hasta que humee. Rocíe la piña con aceite en spray bajo en calorías y áselas 2 minutos por cada lado, hasta que queden agradablemente chamuscadas con marcas de la parrilla.","Precaliente el grill a temperatura alta. Coloque el pollo sobre una rejilla puesta sobre una bandeja para hornear y áselo en el grill de 20 a 25 minutos, volteándolo de vez en cuando, hasta que esté bien cocido (compruébelo con un termómetro para carne o introduciendo un pincho de metal en la parte más gruesa del pollo: si los jugos salen claros, está cocido. Si no, devuélvalo al grill de 4 a 5 minutos y vuelva a comprobar).","Mientras se cocina el pollo, mezcle las zanahorias, las manzanas y el vinagre de sidra. Sazone con pimienta negra recién molida y espolvoree las semillas. Sirva con el pollo y la salsa. Esparza un poco más de cilantro y chile rojo sobre el pollo, si lo desea."],
["Esta receta es alta en proteínas y vitamina C, y es fuente de hierro.",*fv(2)[0]]),
"ar":L("دجاج الجيرك مع صلصة الأناناس المشوية","طبق جامايكي كلاسيكي محبوب في أنحاء منطقة الكاريبي. يشير الجيرك إلى التتبيلة الحارة التي يُنقع فيها الدجاج. يمكن طهيه في الفرن أو على الشواء.","4","385 غ",
["8 أفخاذ دجاج صغيرة منزوعة العظم (720 غ)","3 حبات بهار جامايكي","1 ملعقة صغيرة جوزة الطيب المطحونة","1 ملعقة صغيرة قرفة مطحونة","1 بصلة حمراء صغيرة، مبشورة ناعمًا","4 حبات بصل أخضر، مقطوعة الأطراف ومفرومة ناعمًا","1 حبة فلفل حار أحمر، منزوعة البذور ومفرومة ناعمًا","1 حبة ليمون أخضر، قشرها مبشور ناعمًا وعصيرها",["لصلصة الأناناس","1 حبة أناناس طازجة متوسطة الحجم، منزوعة القشرة، أو 8 حلقات أناناس معلب"],["لصلصة الأناناس","بخاخ زيت 1 سعرة"],["لصلصة الأناناس","1 حبة فلفل حار أخضر، منزوعة البذور ومفرومة ناعمًا"],["لصلصة الأناناس","1 حبة ليمون أخضر، العصير فقط"],["لصلصة الأناناس","½ بصلة حمراء صغيرة، مفرومة ناعمًا"],["لصلصة الأناناس","حفنة صغيرة من الكزبرة الخضراء الطازجة، مفرومة ناعمًا"],["لسلطة الجزر والتفاح","2 جزرة، مقشرة ومبشورة خشنًا"],["لسلطة الجزر والتفاح","1 تفاحة غراني سميث، منزوعة القلب ومبشورة خشنًا"],["لسلطة الجزر والتفاح","2 ملعقة صغيرة خل التفاح"],["لسلطة الجزر والتفاح","1 ملعقة كبيرة بذور عباد الشمس"]],
["باستخدام سكين حادة، اجرح لحم الدجاج عدة جرحات وضعه في وعاء غير معدني. حمّص حبات البهار الجامايكي دون زيت لمدة 2–3 دقائق حتى تفوح رائحتها، ثم ضعها في هاون ودقّها حتى تصبح مسحوقًا. أضف بقية مكونات الجيرك ودقّها حتى تصبح معجونًا سميكًا. قلّبه مع الدجاج ليتغطى بالتساوي. غطِّه واتركه ليتتبل طوال الليل إن توفر لديك الوقت، أو لمدة ساعة واحدة على الأقل.","في هذه الأثناء، اقطع قلب الأناناس وتخلّص منه وقطّع اللب شرائح. سخّن مقلاة شواء حتى يتصاعد منها الدخان. رشّ الأناناس ببخاخ طهي قليل السعرات واشوِه دقيقتين على كل جانب حتى يتفحم بشكل جميل مع ظهور خطوط الشواء.","سخّن الشواية مسبقًا على درجة عالية. ضع الدجاج على رف الشواية فوق صينية خبز واشوِه من 20 إلى 25 دقيقة مع قلبه من حين لآخر حتى ينضج تمامًا (تحقق باستخدام ميزان حرارة اللحم أو بغرس سيخ معدني في أسمك جزء من الدجاج – إذا خرج العصارة صافية فقد نضج. وإلا فأعده تحت الشواية من 4 إلى 5 دقائق ثم اختبره مرة أخرى).","بينما يُطهى الدجاج، اخلط الجزر والتفاح وخل التفاح. تبّلها بالفلفل الأسود المطحون طازجًا وانثر البذور فوقها. قدّمها مع الدجاج والصلصة. انثر قليلًا من الكزبرة الخضراء والفلفل الحار الأحمر الإضافي فوق الدجاج إن رغبت."],
["هذه الوصفة غنية بالبروتين وفيتامين ج، وهي مصدر للحديد.",*fv(2)[1]])}))
I.append((7017274,{
"es":L("Filete de cordero con cuscús a la menta","Esta apetitosa receta con menta fresca picada es un plato ideal para recibir invitados.","4","350g",
["450g de filete de cordero magro","pimienta negra recién molida","2 cucharadas de jalea de grosella roja","400ml de caldo de verduras (use caldo de verduras sin gluten para que esta receta sea sin gluten)","2 cucharaditas de cilantro molido","2 cucharaditas de comino molido","175g de cuscús (use quinua para que esta receta sea sin gluten)","1 cucharada de menta fresca picada","4 tomates, picados","2 cucharadas de perejil picado","jugo y ralladura de 1 limón"],
["Coloque el cordero en una bandeja para hornear y sazone con pimienta negra.","Caliente la jalea de grosella roja y vierta sobre el cordero. Use una brocha de repostería para extender la jalea por toda la superficie.","Cocine el cordero bajo un grill caliente de 10 a 15 minutos. Retire del grill, cubra con papel de aluminio y deje reposar durante 5 minutos.","Mientras tanto, lleve el caldo de verduras a ebullición y añada las especias. Agregue el cuscús, retire del fuego y tape con una tapa. Deje que se cocine al vapor durante 1 minuto y luego suelte los granos con un tenedor.","Incorpore la menta picada, los tomates, el perejil, el jugo de limón y la ralladura, y sirva en montoncitos sobre los platos.","Corte el cordero en rebanadas finas y colóquelas sobre el cuscús."],
["También podría usar pechuga de pollo o filete de cerdo con esta receta.","Instrucciones para congelar: Congele el cuscús y el cordero por separado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.",*fv(1)[0]]),
"ar":L("فيليه ضأن مع كسكس بالنعناع","هذه الوصفة الشهية التي تجمع النعناع الطازج المفروم هي طبق مثالي لاستقبال الضيوف.","4","350 غ",
["450 غ فيليه ضأن قليل الدسم","فلفل أسود مطحون طازجًا","2 ملعقة كبيرة جيلي الكشمش الأحمر","400 مل مرق خضار (استخدم مرق خضار خاليًا من الغلوتين لتكون هذه الوصفة خالية من الغلوتين)","2 ملعقة صغيرة كزبرة مطحونة","2 ملعقة صغيرة كمون مطحون","175 غ كسكس (استخدم الكينوا لتكون هذه الوصفة خالية من الغلوتين)","1 ملعقة كبيرة نعناع طازج مفروم","4 حبات طماطم، مفرومة","2 ملعقة كبيرة بقدونس، مفروم","عصير وقشر 1 ليمونة"],
["ضع الضأن على صينية خبز وتبّله بالفلفل الأسود.","سخّن جيلي الكشمش الأحمر واسكبه على الضأن. استخدم فرشاة معجنات لدهن الجيلي على كامل السطح.","اشوِ الضأن تحت شواية ساخنة من 10 إلى 15 دقيقة. أخرجه من الشواية وغطِّه بورق الألمنيوم واتركه يرتاح 5 دقائق.","في هذه الأثناء، اترك مرق الخضار حتى يغلي وأضف التوابل. أضف الكسكس وارفعه عن النار وغطِّه بغطاء. اتركه ينضج على البخار لمدة دقيقة واحدة ثم فكّك الحبوب بالشوكة.","أضف النعناع المفروم والطماطم والبقدونس وعصير الليمون وقشره وقلّب، ثم كوّمه في أطباق التقديم.","قطّع الضأن إلى شرائح رفيعة ورتّبها فوق الكسكس."],
["يمكنك أيضًا استخدام صدر الدجاج أو فيليه لحم الخنزير مع هذه الوصفة.","تعليمات التجميد: جمّد الكسكس والضأن كلًّا على حدة. ذوّبهما في الثلاجة أو الميكروويف وأعد تسخينهما حتى يسخنا تمامًا من الداخل.",*fv(1)[1]])}))
I.append((7019856,{
"es":L("Sopa mulligatawny","Perfecta para las noches frías, esta sopa picante y reconfortante está repleta de verduras, lentejas y arroz.","8","266g",
["2 cucharaditas de aceite de girasol","1 cebolla grande, finamente picada","1 zanahoria, en cubos","1 camote, en cubos (250g)","1 lata de 400g de tomates","75g de lentejas rojas","2 dientes de ajo, machacados","1 cubito de caldo de verduras","1 cucharada de pasta de curry de intensidad media (o curry en polvo)","1 litro de agua hirviendo","75g de arroz basmati cocido en 1 litro de agua hirviendo","cilantro fresco, para servir"],
["Ponga el aceite en una olla grande con la cebolla. Cocine 5 minutos, revolviendo con frecuencia, hasta que empiece a dorarse.","Añada la zanahoria y el camote, y cocine 5 minutos más, revolviendo con frecuencia.","Ahora agregue los tomates, las lentejas, el ajo, el cubito de caldo, la pasta de curry y 1 litro de agua hirviendo. Lleve a ebullición, baje el fuego, tape y cocine a fuego lento durante 15 minutos.","Mientras tanto, hierva el arroz durante 10 minutos, enjuáguelo en un colador bajo agua fría y reserve.","Licúe las verduras con una batidora de mano o un procesador de alimentos hasta que quede suave.","Incorpore el arroz a la sopa y sirva con un poco de cilantro recién picado espolvoreado."],
["Añada una pechuga de pollo cortada en cubitos finos junto con los tomates y use un cubito de caldo de pollo.","Esta receta es alta en vitamina A, que ayuda a que su sistema inmunitario funcione correctamente.","Instrucciones para congelar: Se puede congelar una vez cocida. Congele en porciones y luego descongele en el refrigerador, o descongele en el microondas revolviendo con frecuencia.",*fv(1)[0]]),
"ar":L("حساء موليغاتاوني","مثالي للأمسيات الباردة، هذا الحساء الحار المُدفئ مليء بالخضار والعدس والأرز.","8","266 غ",
["2 ملعقة صغيرة زيت عباد الشمس","1 بصلة كبيرة، مفرومة ناعمًا","1 جزرة، مقطعة مكعبات","1 حبة بطاطا حلوة، مقطعة مكعبات (250 غ)","1 علبة 400 غ طماطم","75 غ عدس أحمر","2 فص ثوم، مهروس","1 مكعب مرق خضار","1 ملعقة كبيرة معجون كاري متوسط الحدة (أو مسحوق)","1 لتر ماء مغلي","75 غ أرز بسمتي مطبوخ في 1 لتر ماء مغلي","كزبرة خضراء طازجة، للتقديم"],
["ضع الزيت في قدر كبير مع البصل. اطهُه 5 دقائق مع التقليب بانتظام حتى يبدأ بالاحمرار.","أضف الجزر والبطاطا الحلوة، واطهُ 5 دقائق إضافية مع التقليب بانتظام.","أضف الآن الطماطم والعدس والثوم ومكعب المرق ومعجون الكاري و1 لتر من الماء المغلي. اتركه حتى يغلي، ثم اخفض النار وغطِّه واتركه على نار هادئة 15 دقيقة.","في هذه الأثناء، اسلق الأرز 10 دقائق، واشطفه في مصفاة تحت ماء بارد وضعه جانبًا.","اخلط الخضار بخلاط يدوي أو محضّر الطعام حتى تصبح ناعمة.","أضف الأرز إلى الحساء وقدّمه مع رشة من الكزبرة الخضراء المفرومة طازجًا."],
["أضف صدر دجاج مقطعًا مكعبات صغيرة جدًا مع الطماطم واستخدم مكعب مرق دجاج.","هذه الوصفة غنية بفيتامين أ، الذي يساعد جهازك المناعي على العمل بشكل سليم.","تعليمات التجميد: مناسب للتجميد بعد الطهي. جمّده في حصص ثم ذوّبه في الثلاجة، أو ذوّبه في الميكروويف مع التقليب بانتظام.",*fv(1)[1]])}))
I.append((7023571,{
"es":L("Tostada galesa de puerro (Welsh rarebit)","Una versión sencilla y más saludable del queso sobre pan tostado. Perfecta para el desayuno o el brunch.","2","164g",
["1 cucharadita de aceite de colza","1 puerro grande, finamente picado","2 rebanadas de pan de centeno integral","1 huevo mediano","1 cucharadita colmada de mostaza de Dijon","30g de queso Cheddar curado, finamente rallado"],
["Ponga el aceite en una sartén y añada el puerro picado; cocine a fuego bajo a medio, revolviendo con frecuencia, durante 4 minutos, hasta que esté blando.","Retire el puerro del fuego y déjelo enfriar unos minutos.","Mientras tanto, encienda el grill a temperatura alta y tueste un lado del pan de centeno.","Ponga el huevo en un bol con la mostaza y bata ligeramente. A continuación, incorpore la mitad del queso rallado y todo el puerro.","Extienda la mezcla de manera uniforme sobre el lado sin tostar del pan, espolvoree con el queso restante y gratine unos 2 a 3 minutos, hasta que esté dorado."],
["Usar un Cheddar curado significa que puede usar menos y aun así obtener un sabor intenso.","El pan de centeno es un excelente cereal integral: es alto en fibra y le ayudará a sentirse saciado por más tiempo, por lo que es ideal para el desayuno.",*fv(1)[0]]),
"ar":L("توست الكراث الويلزي (ويلش رابيت)","نسخة بسيطة وأكثر صحة من الجبن على التوست. مثالية للفطور أو وجبة برانش.","2","164 غ",
["1 ملعقة صغيرة زيت اللفت","1 كراث كبير، مفروم ناعمًا","2 شريحة خبز الجاودار بالحبوب الكاملة","1 بيضة متوسطة","1 ملعقة صغيرة مكدسة خردل ديجون","30 غ جبن شيدر معتق، مبشور ناعمًا"],
["ضع الزيت في مقلاة، ثم أضف الكراث المفروم واطهُه على نار هادئة إلى متوسطة مع التقليب المتكرر لمدة 4 دقائق حتى يطرى.","ارفع الكراث عن النار واتركه ليبرد بضع دقائق.","في هذه الأثناء، شغّل الشواية على درجة عالية وحمّص أحد جانبي خبز الجاودار.","ضع البيض في وعاء مع الخردل واخفقه خفقًا خفيفًا. ثم أضف نصف الجبن المبشور وكل الكراث وقلّب.","افرد الخليط بالتساوي على الجانب غير المحمص من الخبز، وانثر عليه الجبن المتبقي واشوِه تحت الشواية لحوالي 2–3 دقائق حتى يصبح بنيًّا ذهبيًّا."],
["استخدام جبن الشيدر المعتق يعني أنك تستطيع استخدام كمية أقل والحصول على نكهة قوية.","خبز الجاودار من الحبوب الكاملة الممتازة – فهو غني بالألياف وسيبقيك تشعر بالشبع لفترة أطول، لذا فهو مثالي للفطور.",*fv(1)[1]])}))
I.append((7025833,{
"es":L("Sándwich abierto de sardinas con chile","Un almuerzo sabroso y abundante que puede preparar en menos de 5 minutos.","1","190g",
["½ chile rojo pequeño (10g)","2 rebanadas pequeñas de pan integral (40g)","1 lata de 120g de sardinas en aceite de oliva","rúcula (40g)"],
["Quite las semillas a ½ chile rojo pequeño y córtelo en rodajas finas.","Escurra una lata de sardinas, reservando un poco del aceite.","Ponga un puñado de rúcula sobre las rebanadas de pan y coloque las sardinas encima.","Esparza las rodajas de chile y rocíe con un poco del aceite reservado."],
[[FV_ES,"Porciones de fruta/verdura por ración: 0"]]),
"ar":L("ساندويتش السردين المفتوح بالفلفل الحار","غداء لذيذ ومشبع يمكنك تحضيره في أقل من 5 دقائق.","1","190 غ",
["½ حبة فلفل حار أحمر صغيرة (10 غ)","2 شريحة صغيرة من خبز القمح الكامل (40 غ)","1 علبة 120 غ سردين في زيت الزيتون","جرجير (40 غ)"],
["انزع بذور ½ حبة فلفل حار أحمر صغيرة وقطّعها شرائح رفيعة.","صفِّ علبة السردين مع الاحتفاظ ببعض الزيت.","ضع حفنة من الجرجير فوق شريحتي الخبز ورتّب السردين فوقها.","انثر شرائح الفلفل الحار ورشّ قليلًا من الزيت المحتفظ به."],
[[FV_AR,"حصص الفاكهة/الخضار لكل حصة: 0"]])}))
I.append((7026697,{
"es":L("Mini tartaletas de salmón ahumado y cebollín","Bocaditos de mariscos apetitosos, estupendos para servir con bebidas.","36","18g",
["350g de masa quebrada ya preparada","1 huevo, batido","150ml de crème fraîche ligera","2 cucharadas de cebollín, picado","75g de salmón ahumado, picado grueso","pimienta negra recién molida"],
["Precaliente el horno a 200ºC/gas 6.","Extienda la masa en una capa fina. Corte unos 36 círculos de 5cm con un cortador de masa y úselos para forrar moldes para mini tartaletas. Hornee en blanco durante 10 minutos.","Bata juntos el huevo y la crème fraîche, sazone bien y luego incorpore el cebollín y el salmón.","Ponga con una cuchara un poco de la mezcla en cada una de las bases de masa y hornee unos 10 minutos, hasta que estén doradas y cuajadas.","Deje enfriar un poco y sirva."],
["Podría usar jamón ahumado en lugar de salmón.","Para una versión vegetariana, use tomates secos al sol en rodajas en lugar del salmón ahumado.",[FV_ES,"Porciones de fruta/verdura por ración: 0"]]),
"ar":L("تارتلات صغيرة بالسلمون المدخن والثوم المعمر","لقيمات شهية من المأكولات البحرية، رائعة للتقديم مع المشروبات.","36","18 غ",
["350 غ عجينة بريزيه جاهزة","1 بيضة، مخفوقة","150 مل كريم فريش خفيف","2 ملعقة كبيرة ثوم معمر (شيف)، مفروم","75 غ سلمون مدخن، مفروم فرمًا خشنًا","فلفل أسود مطحون طازجًا"],
["سخّن الفرن مسبقًا إلى 200° مئوية/علامة الغاز 6.","افرد العجينة رقيقة. اقطع حوالي 36 دائرة بقطر 5 سم بقاطعة المعجنات واستخدمها لتبطين قوالب التارتلات الصغيرة. اخبزها خبزًا أوليًّا فارغة لمدة 10 دقائق.","اخفق البيض والكريم فريش معًا، وتبّل جيدًا ثم أضف الثوم المعمر والسلمون وقلّب.","ضع قليلًا من الخليط بالملعقة في كل قاعدة من العجين واخبزها لحوالي 10 دقائق، حتى تصبح ذهبية ومتماسكة.","اتركها لتبرد قليلًا وقدّمها."],
["يمكنك استخدام لحم الخنزير المدخن (الهام) بدلًا من السلمون.","لنسخة نباتية، استخدم شرائح الطماطم المجففة بالشمس بدلًا من السلمون المدخن.",[FV_AR,"حصص الفاكهة/الخضار لكل حصة: 0"]])}))
I.append((7032450,{
"es":L("Musaka de verduras","Un plato abundante pero bajo en grasa, lleno de verduras y más alto en fibra, cubierto con yogur especiado con queso.","6","245g",
["1 camote (aprox. 350g), pelado y cortado en rodajas de 0.5cm de grosor","1 berenjena, en rodajas finas","1 cucharadita de aceite de colza","2 cebollas medianas, finamente picadas","3 dientes de ajo, picados","1 pimiento rojo, finamente picado","1 pimiento amarillo, finamente picado","1 calabacín, en cubitos finos","1 zanahoria, rallada","1 lata de 400g de lentejas, escurridas","1 lata de 400g de tomates","1 cucharadita de orégano","1 cucharadita de tomillo",["Para la cobertura","200g de yogur griego con 0% de grasa"],["Para la cobertura","50g de Cheddar semidescremado, finamente rallado"],["Para la cobertura","1 cucharadita colmada de canela molida"]],
["Precaliente el horno a 180°C/gas 4. Hierva las rodajas de camote de 7 a 10 minutos, hasta que estén apenas tiernas. Escurra y reserve.","Ase las rodajas de berenjena en el grill 4 minutos por cada lado y reserve.","Ponga el aceite en una sartén y añada las cebollas. Cuando empiecen a dorarse, agregue los pimientos, los calabacines y las zanahorias. Cocine 5 minutos.","Añada el ajo, las lentejas, los tomates, el orégano y el tomillo. Lleve a ebullición, baje el fuego, tape y cocine a fuego lento durante 5 minutos.","Mientras tanto, para preparar la cobertura, mezcle el yogur, el Cheddar y la canela.","En un recipiente apto para horno, coloque una capa de berenjena, añada una cucharada de la mezcla de lentejas y tomate, seguida de una capa de camote. Cubra con más mezcla de lentejas y tomate, y alterne las capas, terminando con la berenjena.","Extienda con una cuchara la mezcla de yogur por encima y hornee durante 15 minutos."],
["Podría preparar musaka individuales en recipientes aptos para horno para servir directamente en la mesa.","Para obtener el mejor sabor, deje reposar de 5 a 10 minutos antes de servir.","Instrucciones para congelar: Se puede congelar una vez cocida. Descongele en el refrigerador o en el microondas y recaliente bien hasta que esté bien caliente por completo.",*fv(3)[0]]),
"ar":L("مسقعة الخضار","طبق مشبع لكنه أقل دسمًا، مليء بالخضار وأعلى في الألياف، يعلوه زبادي متبّل بالجبن.","6","245 غ",
["1 حبة بطاطا حلوة (حوالي 350 غ)، مقشرة ومقطعة إلى شرائح بسماكة 0.5 سم","1 حبة باذنجان، مقطعة شرائح رفيعة","1 ملعقة صغيرة زيت اللفت","2 بصلة متوسطة، مفرومة ناعمًا","3 فص ثوم، مفروم","1 حبة فلفل أحمر، مفرومة ناعمًا","1 حبة فلفل أصفر، مفرومة ناعمًا","1 كوسا، مقطعة مكعبات صغيرة","1 جزرة، مبشورة","1 علبة 400 غ عدس، مصفى","1 علبة 400 غ طماطم","1 ملعقة صغيرة أوريغانو","1 ملعقة صغيرة زعتر",["للتغطية","200 غ زبادي يوناني خالٍ من الدسم 0%"],["للتغطية","50 غ جبن شيدر نصف دسم، مبشور ناعمًا"],["للتغطية","1 ملعقة صغيرة مكدسة قرفة مطحونة"]],
["سخّن الفرن مسبقًا إلى 180° مئوية/علامة الغاز 4. اسلق شرائح البطاطا الحلوة من 7 إلى 10 دقائق حتى تلين بالكاد. صفِّها وضعها جانبًا.","اشوِ شرائح الباذنجان تحت الشواية 4 دقائق على كل جانب وضعها جانبًا.","ضع الزيت في مقلاة وأضف البصل. عندما يبدأ بالاحمرار، أضف الفلفل والكوسا والجزر. اطهُ 5 دقائق.","أضف الثوم والعدس والطماطم والأوريغانو والزعتر. اتركه حتى يغلي، ثم اخفض النار وغطِّه واتركه على نار هادئة 5 دقائق.","في هذه الأثناء، لتحضير التغطية اخلط الزبادي والشيدر والقرفة.","في طبق يتحمل حرارة الفرن، ضع طبقة من الباذنجان، ثم أضف ملعقة من خليط العدس والطماطم، تليها طبقة من البطاطا الحلوة. غطِّها بمزيد من خليط العدس والطماطم، وكرّر الطبقات بالتناوب، وأنهِها بطبقة الباذنجان.","وزّع خليط الزبادي بالملعقة فوقها واخبزها 15 دقيقة."],
["يمكنك تحضير مسقعة فردية في أطباق تتحمل حرارة الفرن وتقديمها مباشرة إلى المائدة.","للحصول على أفضل نكهة، اتركها ترتاح من 5 إلى 10 دقائق قبل التقديم.","تعليمات التجميد: مناسبة للتجميد بعد الطهي. ذوّبها في الثلاجة أو الميكروويف وأعد تسخينها جيدًا حتى تسخن تمامًا من الداخل.",*fv(3)[1]])}))
I.append((7034454,{
"es":L("Mini budines navideños","Versión más saludable en tamaño de bocado del budín navideño tradicional. Sin azúcar añadida, y con avena molida, plátano machacado y manzana en lugar del tradicional sebo (grasa animal).","24","35g",
["350g de frutas secas variadas","3 higos secos, picados","1 cucharadita de mezcla de especias","1 cucharadita de canela molida","1 cucharadita de jengibre molido","1 pizca de clavo molido","250ml de agua hirviendo","1 plátano grande (150g)","1 manzana sin pelar, rallada","75g de avena fina","60g de almendras molidas","25g de semillas de girasol","ralladura de 1 naranja","2 cucharaditas de aceite de girasol, para engrasar"],
["Precaliente el horno a 170°C/gas 3. Ponga las frutas secas, los higos y las especias en un bol. Mezcle y luego añada el agua hirviendo, tape y deje reposar durante 15 minutos.","Mientras tanto, machaque el plátano e incorpore la manzana rallada, la avena, las almendras molidas, las semillas y la ralladura.","A continuación, combine todo en un solo bol, mezclando bien.","Engrase ligeramente dos moldes para mini panecillos de 12 cavidades (o simplemente haga 2 tandas en el mismo molde) y coloque la mezcla en los moldes.","Hornee durante 15 a 25 minutos, según el tamaño de los moldes.","Cuando estén cocidos (están firmes y un cuchillo sale limpio), desmolde sobre una rejilla y deje enfriar."],
["Puede usar un molde de cualquier tamaño; simplemente ajuste el tiempo de cocción en consecuencia, ya que los panecillos más grandes tardarán más en cocerse.","Estos budines pequeños se cocinan mucho más rápido y no es necesario cocerlos al vapor, por lo que también son ideales para fiestas previas a la Navidad.","Pruebe a cubrirlos con nueces o rodajas de naranja para obtener budines de súper lujo.","Instrucciones para congelar: Descongele en el microondas y luego cueza al vapor, en el microondas o caliente en un horno moderado.",[FV_ES,"Porciones de fruta/verdura por ración: 0"]]),
"ar":L("بودينغ الكريسماس الصغير","نسخة أصغر حجمًا بحجم لقمة وأكثر صحة من بودينغ الكريسماس التقليدي. بدون سكر مضاف، ومع دقيق الشوفان والموز المهروس والتفاح بدلًا من شحم الكلى التقليدي (دهن حيواني).","24","35 غ",
["350 غ فواكه مجففة مشكلة","3 حبات تين مجفف، مفرومة","1 ملعقة صغيرة خليط توابل","1 ملعقة صغيرة قرفة مطحونة","1 ملعقة صغيرة زنجبيل مطحون","رشة قرنفل مطحون","250 مل ماء مغلي","1 موزة كبيرة (150 غ)","1 تفاحة غير مقشرة، مبشورة","75 غ دقيق شوفان ناعم","60 غ لوز مطحون","25 غ بذور عباد الشمس","قشر مبشور من 1 برتقالة","2 ملعقة صغيرة زيت عباد الشمس، للدهن"],
["سخّن الفرن مسبقًا إلى 170° مئوية/علامة الغاز 3. ضع الفواكه المشكلة والتين والتوابل في وعاء. امزجها ثم أضف الماء المغلي وغطِّها واتركها 15 دقيقة.","في هذه الأثناء، اهرس الموز وأضف التفاح المبشور ودقيق الشوفان واللوز المطحون والبذور والقشر وامزج.","بعد ذلك، اجمع كل شيء في وعاء واحد، وامزج جيدًا.","ادهن قالبين صغيرين لكعك الكب كيك من 12 تجويفًا بالزيت قليلًا (أو ببساطة اعمل دفعتين في القالب نفسه) وضع الخليط في القالبين.","اخبزها في الفرن من 15 إلى 25 دقيقة، حسب حجم القوالب.","عندما تنضج (تكون متماسكة ويخرج السكين نظيفًا)، اقلبها على رف سلكي واتركها لتبرد."],
["يمكنك استخدام قالب بأي حجم، فقط اضبط وقت الطهي وفقًا لذلك، فالكعكات الأكبر تحتاج إلى وقت أطول.","تُطهى هذه البودينغات الصغيرة بشكل أسرع بكثير ولا تحتاج إلى طهيها على البخار، مما يجعلها مثالية أيضًا لحفلات ما قبل الكريسماس.","جرّب تغطيتها بالمكسرات أو شرائح البرتقال لتحصل على بودينغ فاخر للغاية.","تعليمات التجميد: ذوّبها في الميكروويف ثم اطهها على البخار أو في الميكروويف أو سخّنها في فرن معتدل.",[FV_AR,"حصص الفاكهة/الخضار لكل حصة: 0"]])}))
I.append((7034894,{
"es":L("Gajos de papa picantes","Estupendos para recibir invitados y deliciosamente saludables: mucho más bajos en grasa que las versiones compradas. Tenga en cuenta: las salsas para mojar no están incluidas en el análisis.","8","317g",
["8 papas para hornear, cada una cortada en 8 gajos (peso total 1.6kg)","3 cucharadas de aceite de colza","1 cucharada de pimentón",["Para la salsa de ajo y hierbas","1 envase de 200g de queso crema semidescremado"],["Para la salsa de ajo y hierbas","1 envase de 200g de fromage frais sin grasa"],["Para la salsa de ajo y hierbas","2 dientes de ajo, machacados"],["Para la salsa de ajo y hierbas","3 cucharadas de menta fresca, picada"],["Para la salsa de ajo y hierbas","3 cucharadas de perejil fresco, picado"],["Para la salsa de tomate picante","1 lata de 400g de tomates picados"],["Para la salsa de tomate picante","1 chile rojo"],["Para la salsa de tomate picante","1 diente de ajo, machacado"],["Para la salsa de tomate picante","3 cucharadas de cilantro fresco, picado"]],
["Precaliente el horno a 200ºC/gas 6.","Coloque los gajos de papa en una olla grande con agua hirviendo y cocine a fuego lento durante 5 minutos. Escurra y pase a una fuente grande para asar.","Mezcle el aceite y el pimentón y revuelva con los gajos de papa. Colóquelos en una bandeja para hornear y cocine de 20 a 25 minutos, hasta que estén dorados y crujientes.","Para la salsa de ajo y hierbas, simplemente combine todos los ingredientes y póngalos con una cuchara en un plato para servir.","Escurra el exceso de líquido de los tomates y luego licúelos con el chile, el ajo y el cilantro durante 30 segundos. Póngalos con una cuchara en un plato para servir.","Sirva las papas con las salsas."],
["Si los va a pasar como bocadillos para comer con las manos, omita el pimentón de las papas, ¡porque mancha los dedos!","Podría usar polvo de cinco especias chinas en lugar de pimentón, o probar con tomillo seco.","Instrucciones para congelar: Los gajos se pueden congelar. Descongele en el microondas y recaliente en el horno hasta que estén bien calientes.",*fv(0)[0]]),
"ar":L("أصابع بطاطس حارة","رائعة لاستقبال الضيوف وصحية بشكل مبهج – أقل دسمًا بكثير من النسخ الجاهزة المشتراة. يرجى الملاحظة: الصلصات للغمس غير مشمولة في التحليل.","8","317 غ",
["8 حبات بطاطس للخبز، كل واحدة مقطعة إلى 8 أصابع (الوزن الإجمالي 1.6 كغ)","3 ملاعق كبيرة زيت اللفت","1 ملعقة كبيرة بابريكا",["لصلصة الثوم والأعشاب","1 علبة 200 غ جبن كريمي نصف دسم"],["لصلصة الثوم والأعشاب","1 عبوة 200 غ فرماج فريه خالٍ من الدسم"],["لصلصة الثوم والأعشاب","2 فص ثوم، مهروس"],["لصلصة الثوم والأعشاب","3 ملاعق كبيرة نعناع طازج، مفروم"],["لصلصة الثوم والأعشاب","3 ملاعق كبيرة بقدونس طازج، مفروم"],["لصلصة الطماطم الحارة","1 علبة 400 غ طماطم مفرومة"],["لصلصة الطماطم الحارة","1 حبة فلفل حار أحمر"],["لصلصة الطماطم الحارة","1 فص ثوم، مهروس"],["لصلصة الطماطم الحارة","3 ملاعق كبيرة كزبرة خضراء طازجة، مفرومة"]],
["سخّن الفرن مسبقًا إلى 200° مئوية/علامة الغاز 6.","ضع أصابع البطاطس في قدر كبير من الماء المغلي واتركها على نار هادئة 5 دقائق. صفِّها وضعها في صينية شوي كبيرة.","اخلط الزيت والبابريكا وقلّب به أصابع البطاطس. ضعها على صينية خبز واخبزها من 20 إلى 25 دقيقة حتى تصبح ذهبية ومقرمشة.","لصلصة الثوم والأعشاب، ما عليك سوى خلط جميع المكونات ووضعها بالملعقة في طبق تقديم.","صفِّ أي سائل زائد من الطماطم ثم اخلطها مع الفلفل الحار والثوم والكزبرة الخضراء لمدة 30 ثانية. ضعها بالملعقة في طبق تقديم.","قدّم البطاطس مع الصلصات."],
["إذا كنت ستقدمها كأطعمة تُؤكل باليد، فاحذف البابريكا من البطاطس لأنها تلطخ الأصابع!","يمكنك استخدام مسحوق البهارات الصينية الخمسة بدلًا من البابريكا، أو جرّب الزعتر المجفف.","تعليمات التجميد: الأصابع مناسبة للتجميد. ذوّبها في الميكروويف وأعد تسخينها في الفرن حتى تسخن جيدًا.",*fv(0)[1]])}))
I.append((7037421,{
"es":L("Panqueques integrales de espinacas y queso Cheddar","Panqueques contundentes y con queso, cubiertos con tomates y albahaca.","4","203g",
["2 cucharaditas de aceite de girasol","1 cebolla grande, finamente picada","1 huevo, batido","150ml de leche semidescremada","100g de harina integral","200g de espinacas congeladas, descongeladas y sin exceso de agua","50g de queso Cheddar curado reducido en grasa, cortado en cubitos finos","1 buena pizca de pimienta blanca","20 tomates cherry, cortados en cuartos","10g de albahaca fresca, picada","1 pizca de pimienta negra"],
["Ponga 1 cucharadita de aceite en una cacerola a fuego bajo a medio y luego añada la cebolla. Cocine de 3 a 4 minutos, revolviendo con frecuencia, hasta que se ablande, y retire del fuego.","Bata el huevo con la leche; luego ponga la harina en un bol e incorpore poco a poco la mezcla de leche hasta que quede suave. A continuación, añada las espinacas, la cebolla, el queso y la pimienta, y mezcle.","Caliente una sartén antiadherente a fuego medio a bajo. Agregue la cucharadita de aceite restante y extiéndala por la sartén con papel de cocina antes de añadir ¼ de la mezcla. Extiéndala por la sartén con el dorso de una cuchara, hasta formar un círculo de unos 12 a 15cm de diámetro y ½cm de grosor.","Cocine de 2 a 3 minutos, luego voltee con una espátula y cocine uno o dos minutos más por el otro lado. Sirva cubierto con tomates frescos espolvoreados con albahaca y pimienta negra."],
["Pruebe a añadir otras verduras a los panqueques, como calabacín rallado, puerros cocidos o champiñones.","Mantenga los panqueques calientes entre dos platos, sobre una olla con agua hirviendo a fuego lento, hasta que estén todos cocidos.",*fv(1)[0]]),
"ar":L("بان كيك القمح الكامل بالسبانخ والشيدر","بان كيك سميك بالجبن يعلوه الطماطم والريحان.","4","203 غ",
["2 ملعقة صغيرة زيت عباد الشمس","1 بصلة كبيرة، مفرومة ناعمًا","1 بيضة، مخفوقة","150 مل حليب نصف خالي الدسم","100 غ دقيق قمح كامل","200 غ سبانخ مجمدة، مذابة ومعصورة من الماء الزائد","50 غ جبن شيدر معتق مخفض الدسم، مقطع مكعبات صغيرة","رشة جيدة من الفلفل الأبيض","20 حبة طماطم كرزية، مقطعة أرباعًا","10 غ ريحان طازج، مفروم","رشة فلفل أسود"],
["ضع 1 ملعقة صغيرة من الزيت في قدر على نار هادئة إلى متوسطة، ثم أضف البصل. اطهُه من 3 إلى 4 دقائق مع التقليب بانتظام حتى يطرى، ثم ارفعه عن النار.","اخفق البيض مع الحليب، ثم ضع الدقيق في وعاء وأضف خليط الحليب تدريجيًا مع التقليب حتى يصبح ناعمًا. بعد ذلك، أضف السبانخ والبصل والجبن والفلفل وامزج.","سخّن مقلاة غير لاصقة على نار متوسطة إلى هادئة. أضف ملعقة الزيت الصغيرة المتبقية وامسح بها المقلاة بمنديل مطبخ، قبل إضافة ¼ الخليط. افرده في المقلاة بظهر ملعقة، بقطر حوالي 12–15 سم وسماكة ½ سم.","اطهُه من 2 إلى 3 دقائق، ثم اقلبه بملعقة التقليب المسطحة واطهُه دقيقة أو دقيقتين من الجانب الآخر. قدّمه مغطى بالطماطم الطازجة المرشوشة بالريحان والفلفل الأسود."],
["جرّب إضافة خضار أخرى إلى البان كيك مثل الكوسا المبشورة أو الكراث المطهو أو الفطر.","حافظ على سخونة البان كيك بين طبقين فوق قدر من الماء الذي يغلي بهدوء، حتى ينضج كله.",*fv(1)[1]])}))
I.append((7040748,{
"es":L("Hamburguesas de frijoles de ojo negro, queso feta y hierbas","Una sabrosa hamburguesa sin carne, rica en proteínas.","6","158g",
["2 cucharaditas de aceite de oliva","3 cebolletas, finamente picadas","1 lata de 400g de frijoles de ojo negro, escurridos y enjuagados","75g de pan rallado integral de granos variados","100g de queso feta, desmenuzado","2 cucharadas de hierbas frescas variadas, picadas","1 huevo, batido","panecillos integrales, para servir (4 de 70g)","ensalada, cebolla morada y tomate"],
["Caliente la mitad del aceite en una sartén antiadherente y fría las cebolletas de 1 a 2 minutos, hasta que se ablanden.","Ponga los frijoles de ojo negro en un bol grande y macháquelos de forma gruesa. Incorpore los demás ingredientes y mezcle bien.","Divida la mezcla en 6 porciones y forme con cada una tortitas u hamburguesas.","Colóquelas en una bandeja para hornear, unte cada lado con el aceite restante y refrigere durante al menos 30 minutos, o hasta que las necesite. Cocine de 2 a 3 minutos por cada lado en una barbacoa o un grill a temperatura media, hasta que estén bien cocidas.","Sirva en un panecillo integral y rellene con ensalada verde, tomates y cebolla morada."],
["El análisis nutricional anterior incluye un panecillo integral como sugerencia de presentación.","Podría usar otros frijoles, como frijoles rojos, cannellini o frijoles mixtos.","Añada ajo machacado y hojuelas de chile para darle más sabor.","Reduzca los carbohidratos disfrutando esta hamburguesa vegetariana sin el panecillo.","Instrucciones para congelar: Congele en porciones envueltas individualmente, con papel encerado entre cada hamburguesa. Descongele por completo y recaliente hasta que estén bien calientes por completo.",[FV_ES,"Porciones de fruta/verdura por ración: 0"]]),
"ar":L("برغر الفاصولياء بعين السمكة وجبن الفيتا والأعشاب","برغر لذيذ خالٍ من اللحم وغني بالبروتين.","6","158 غ",
["2 ملعقة صغيرة زيت زيتون","3 حبات بصل أخضر، مقطعة شرائح رفيعة","1 علبة 400 غ فاصولياء بعين السمكة (لوبيا)، مصفاة ومشطوفة","75 غ فتات خبز جرانري","100 غ جبن فيتا، مفتت","2 ملعقة كبيرة أعشاب طازجة مشكلة، مفرومة","1 بيضة، مخفوقة","خبز لفائف القمح الكامل، للتقديم (4 × 70 غ)","سلطة وبصل أحمر وطماطم"],
["سخّن نصف كمية الزيت في مقلاة غير لاصقة وقلّب البصل الأخضر من 1 إلى 2 دقيقة، حتى يطرى.","ضع الفاصولياء بعين السمكة في وعاء كبير واهرسها هرسًا خشنًا. أضف بقية المكونات وامزج جيدًا.","قسّم الخليط إلى 6 أجزاء وشكّل كل جزء على هيئة أقراص أو برغر.","ضعها على صينية خبز، وادهن كل جانب بالزيت المتبقي وضعها في الثلاجة لمدة 30 دقيقة على الأقل، أو حتى الحاجة. اطهُها من 2 إلى 3 دقائق على كل جانب على شواء أو شواية متوسطة الحرارة حتى تنضج تمامًا.","قدّمه في رغيف من القمح الكامل واحشه بالسلطة الخضراء والطماطم والبصل الأحمر."],
["يشمل التحليل الغذائي أعلاه رغيف قمح كامل كاقتراح للتقديم.","يمكنك استخدام فاصولياء أخرى مثل الفاصولياء الحمراء أو الكانيليني أو الفاصولياء المشكلة.","أضف الثوم المهروس ورقائق الفلفل الحار لمزيد من النكهة.","قلّل الكربوهيدرات بالاستمتاع بهذا البرغر النباتي دون الرغيف.","تعليمات التجميد: جمّده في حصص ملفوفة بشكل فردي مع ورق مقاوم للدهون بين كل قطعة برغر. ذوّبه تمامًا وأعد تسخينه حتى يسخن تمامًا من الداخل.",[FV_AR,"حصص الفاكهة/الخضار لكل حصة: 0"]])}))
save(3,I)
